def verify_token(token):
    if token != "valid-token":
        raise PermissionError("invalid token")
    return {"user": "ana"}


def with_dependency(dependency, route_func):
    def wrapped(*args, **kwargs):
        try:
            auth = dependency(kwargs.pop("token", None))
        except PermissionError as exc:
            return {"status": 401, "error": str(exc)}
        return route_func(*args, auth=auth, **kwargs)
    return wrapped


def protected_route(auth):
    return {"status": 200, "message": "access granted", "auth": auth}


route = with_dependency(verify_token, protected_route)
print(route(token="valid-token"))
print(route(token="wrong-token"))


def logging_middleware(next_handler):
    def handler(request):
        print(f"-> {request['method']} {request['path']}")
        response = next_handler(request)
        print(f"<- {response['status']}")
        return response
    return handler


def final_handler(request):
    return route(token=request.get("token"))


pipeline = logging_middleware(final_handler)
pipeline({"method": "GET", "path": "/protected", "token": "valid-token"})
